using System;using System.IO;using System.Text;using System.Diagnostics;using System.Threading;using System.Security.AccessControl;using System.Security.Principal;using System.Security.Cryptography;using System.Reflection;

// Private backend only. Build generator substitutes a SHA256 of the actual Rust
// compiler image. No managed replacement for canonical compiler output exists.
namespace SentinelHidAdmission {
internal static class UsbHidAdmissionBackendCompiler {
 internal const string ExpectedHash="@COMPILER_SHA256@";
 static string Image{get{return Path.Combine(UsbExactBlockRecoveryTasks.CodeRoot,"hid-compiler-"+ExpectedHash+".exe");}}
 static void Check(bool value){if(!value)throw new InvalidOperationException("Pinned admission compiler refused");}
 static void Security(FileSystemSecurity acl){Check(acl.AreAccessRulesProtected);string owner=acl.GetOwner(typeof(SecurityIdentifier)).Value;Check(owner=="S-1-5-18"||owner=="S-1-5-32-544");bool sy=false,ba=false;foreach(FileSystemAccessRule rule in acl.GetAccessRules(true,true,typeof(SecurityIdentifier))){string sid=rule.IdentityReference.Value;Check(rule.AccessControlType==AccessControlType.Allow&&(sid=="S-1-5-18"||sid=="S-1-5-32-544"));if((rule.FileSystemRights&FileSystemRights.FullControl)==FileSystemRights.FullControl){sy|=sid=="S-1-5-18";ba|=sid=="S-1-5-32-544";}}Check(sy&&ba);}
 static FileStream Pin(){Check(ExpectedHash.Length==64&&(File.GetAttributes(Image)&FileAttributes.ReparsePoint)==0);var file=new FileStream(Image,FileMode.Open,FileAccess.Read,FileShare.Read);try{Security(file.GetAccessControl());Check(file.Length>0&&file.Length<=67108864);using(var hash=SHA256.Create())Check(BitConverter.ToString(hash.ComputeHash(file)).Replace("-","").ToLowerInvariant()==ExpectedHash);file.Position=0;return file;}catch{file.Dispose();throw;}}
 internal static void InstallPrivateFixture(){using(var pin=new SentinelPolicyDirectory(UsbExactBlockRecoveryTasks.CodeRoot)){if(File.Exists(Image)){using(Pin())return;}var acl=new FileSecurity();acl.SetOwner(new SecurityIdentifier(WellKnownSidType.BuiltinAdministratorsSid,null));acl.SetAccessRuleProtection(true,false);foreach(var sid in new[]{WellKnownSidType.LocalSystemSid,WellKnownSidType.BuiltinAdministratorsSid})acl.AddAccessRule(new FileSystemAccessRule(new SecurityIdentifier(sid,null),FileSystemRights.FullControl,AccessControlType.Allow));using(var source=Assembly.GetExecutingAssembly().GetManifestResourceStream("Sentinel.HidAdmission.Compiler")){Check(source!=null&&source.Length>0&&source.Length<=67108864);using(var file=new FileStream(Image,FileMode.CreateNew,FileSystemRights.Read|FileSystemRights.Write,FileShare.None,4096,FileOptions.WriteThrough,acl)){source.CopyTo(file);file.Flush(true);}}using(Pin()){} }}
 sealed class Pump {readonly Thread thread;readonly MemoryStream memory=new MemoryStream();bool ok=true;internal Pump(Stream stream,int limit){thread=new Thread(()=>{try{byte[] bytes=new byte[512];int n;while((n=stream.Read(bytes,0,bytes.Length))!=0){if(memory.Length+n>limit)throw new IOException();memory.Write(bytes,0,n);}}catch{ok=false;}});thread.IsBackground=true;thread.Start();}internal byte[] Finish(){Check(thread.Join(1000)&&ok);return memory.ToArray();}}
 internal static byte[] Compile(global::UsbHidAdmissionPolicy.Snapshot state){if(state==null||!state.Active)return null;byte[] input;using(var memory=new MemoryStream())using(var writer=new BinaryWriter(memory,Encoding.ASCII)){string[] ids=global::UsbHidAdmissionPolicy.CompilerApprovals(state);writer.Write(Encoding.ASCII.GetBytes("SNTINP03"));writer.Write((byte)ids.Length);foreach(string id in ids){byte[] bytes=Encoding.ASCII.GetBytes(id);Check(bytes.Length>0&&bytes.Length<=200);writer.Write((byte)bytes.Length);writer.Write(bytes);}writer.Flush();input=memory.ToArray();}using(Pin())using(var process=new Process()){process.StartInfo=new ProcessStartInfo(Image){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};try{process.Start();var output=new Pump(process.StandardOutput.BaseStream,32768);var error=new Pump(process.StandardError.BaseStream,2048);process.StandardInput.BaseStream.Write(input,0,input.Length);process.StandardInput.Close();Check(process.WaitForExit(5000));byte[] result=output.Finish();error.Finish();Check(process.ExitCode==0);global::UsbSavedAdmissionEntry.DecodePlan(result);return result;}finally{try{if(!process.HasExited){process.Kill();process.WaitForExit(1000);}}catch{}}}}
}
}
